+const BINDINGS = {
+  "mod+s": () => saveDocument(),
+  "mod+z": () => undo(),
+  "mod+shift+z": () => redo(),
+  "mod+b": () => toggleBold(),
+};
+
+export function handleKeydown(e) {
+  const combo = comboString(e);
+  const action = BINDINGS[combo];
+  if (action) { e.preventDefault(); action(); }
+}

